using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using OCRS.Data; using OCRS.Models;
namespace OCRS.Areas.Admin.Controllers;
[Area("Admin"),Authorize(Roles="Admin")] public class SchedulesController(ApplicationDbContext db):Controller { public async Task<IActionResult> Index(int classId){ViewBag.ClassId=classId;return View(await db.ClassSchedules.Where(x=>x.ClassId==classId).OrderBy(x=>x.DayOfWeek).ThenBy(x=>x.StartTime).ToListAsync());} public IActionResult Create(int classId)=>View("Form",new ClassSchedule{ClassId=classId,StartTime=new TimeOnly(18,0),EndTime=new TimeOnly(20,0)}); [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Create(ClassSchedule m){if(m.StartTime>=m.EndTime)ModelState.AddModelError(nameof(m.EndTime),"Giờ kết thúc phải sau giờ bắt đầu.");var instructor=await db.CourseClasses.Where(x=>x.ClassId==m.ClassId).Select(x=>x.InstructorId).SingleAsync();if(instructor!=null&&await db.ClassSchedules.AnyAsync(x=>x.Class.InstructorId==instructor&&x.ClassId!=m.ClassId&&x.DayOfWeek==m.DayOfWeek&&x.StartTime<m.EndTime&&m.StartTime<x.EndTime))ModelState.AddModelError("","Giảng viên bị trùng lịch.");if(!ModelState.IsValid)return View("Form",m);db.Add(m);await db.SaveChangesAsync();return RedirectToAction(nameof(Index),new{classId=m.ClassId});} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Delete(int id){var x=await db.ClassSchedules.FindAsync(id);if(x!=null){var cid=x.ClassId;db.Remove(x);await db.SaveChangesAsync();return RedirectToAction(nameof(Index),new{classId=cid});}return NotFound();} }
